// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();

        c.programOperators(address(this));

        c.updateAlloSettings(address(0x1));


        bool updateSucceeded = false;
        try c.updateRoundImplementation(payable(address(0))) {
            updateSucceeded = true;
        } catch {
            updateSucceeded = false;
        }


        c.updateRoundImplementation(payable(address(0x2)));

        bool updateSucceeded2 = false;
        try c.updateRoundImplementation(payable(address(0))) {
            updateSucceeded2 = true;
        } catch {
            updateSucceeded2 = false;
        }

        assertTrue(c.roundImplementation() == address(0x2) && updateSucceeded2 == false);
    }
}
